<?php
declare(strict_types=1);
require dirname(__DIR__) . '/auth_store.php';
header('Content-Type: application/json; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate');
const TT_BDE_FILE=TT_DATA_DIR.'/accounts.json';
const TT_BDE_MASTER=__DIR__.'/../accounts/accounting_master_v1.json';
function bde_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function bde_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function bde_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))bde_out(['ok'=>false,'error'=>'Direct reconciliation entries are currently available for TTI or BRM PKR banks.'],422);return $v;}
function bde_date(string $v):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))bde_out(['ok'=>false,'error'=>'Valid bank statement date required.'],422);return $v;}
function bde_def():array{return ['revision'=>0,'journals'=>[],'bankAccountSettings'=>[]];}
function bde_names():array{$r=is_file(TT_BDE_MASTER)?file_get_contents(TT_BDE_MASTER):false;$m=$r?json_decode($r,true):null;if(!is_array($m))throw new RuntimeException('Accounting master unavailable.');$o=[];foreach((array)($m['chart']??[]) as $a)if(is_array($a)&&isset($a['code']))$o[(string)$a['code']]=(string)($a['name']??$a['code']);return $o;}
function bde_entity_from_linked(string $v):string{$u=strtoupper($v);if(str_contains($u,'BRM')||str_contains($u,'BUKSH RICE'))return 'BRM';if(str_contains($u,'TTI')||str_contains($u,'TRANSTRADE INTERNATIONAL'))return 'TTI';return '';}
function bde_bank(string $id,string $entity,array $store):array{$m=tt_list_masters();foreach((array)($m['banks']??[]) as $r){if(!is_array($r)||(string)($r['id']??'')!==$id)continue;$v=array_values((array)($r['values']??[]));while(count($v)<14)$v[]='';if(trim((string)$v[0])!=='Company Account'||bde_entity_from_linked((string)$v[1])!==$entity)bde_out(['ok'=>false,'error'=>'Selected bank does not belong to these company books.'],422);$currency=strtoupper(trim((string)$v[7]));if($currency!=='PKR')bde_out(['ok'=>false,'error'=>'Use the foreign-currency banking workflow for non-PKR accounts.'],422);$set=is_array($store['bankAccountSettings'][$id]??null)?$store['bankAccountSettings'][$id]:[];if(array_key_exists('active',$set)&&empty($set['active']))bde_out(['ok'=>false,'error'=>'Selected bank account is inactive in Accounts.'],422);return ['id'=>$id,'bankName'=>(string)$v[4],'accountTitle'=>(string)$v[3],'currency'=>'PKR'];}bde_out(['ok'=>false,'error'=>'Selected bank account was not found.'],404);}
function bde_line(string $account,float $dr,float $cr,array $names,array $extra=[]):array{if(!isset($names[$account]))bde_out(['ok'=>false,'error'=>'Required account '.$account.' is missing from Chart of Accounts.'],422);return array_merge(['account'=>$account,'accountName'=>$names[$account],'debit'=>round($dr,2),'credit'=>round($cr,2)],$extra);}
function bde_next(array $items):string{$n=count($items)+1;do{$id='AUTO-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
try{$u=tt_require_login();if(!tt_user_can_open_module($u,'Accounts'))bde_out(['ok'=>false,'error'=>'Accounts permission required.'],403);if($_SERVER['REQUEST_METHOD']!=='POST')bde_out(['ok'=>false,'error'=>'Method not allowed.'],405);if(!bde_can_write($u))bde_out(['ok'=>false,'error'=>'Accounts Create / Edit / Approve permission required.'],403);$b=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($b)||!tt_verify_csrf((string)($b['csrf']??'')))bde_out(['ok'=>false,'error'=>'Your session expired. Refresh and try again.'],419);$entity=bde_entity((string)($b['entity']??''));$date=bde_date((string)($b['date']??''));$bankId=trim((string)($b['bankId']??''));$type=strtoupper(trim((string)($b['type']??'')));$amount=round((float)($b['amount']??0),2);if($bankId===''||$amount<=0)bde_out(['ok'=>false,'error'=>'Bank and amount are required.'],422);$allowed=['BANK_CHARGE','INTEREST_CHARGED','INTEREST_RECEIVED'];if(!in_array($type,$allowed,true))bde_out(['ok'=>false,'error'=>'Select Bank Charge, Interest Charged or Interest Received.'],422);tt_ensure_data_dir();$h=fopen(TT_BDE_FILE,'c+');if($h===false||!flock($h,LOCK_EX))throw new RuntimeException('Accounts storage unavailable.');try{rewind($h);$raw=stream_get_contents($h);$s=$raw?json_decode($raw,true):null;if(!is_array($s))$s=bde_def();$s=array_replace_recursive(bde_def(),$s);$bank=bde_bank($bankId,$entity,$s);$names=bde_names();$ref=trim((string)($b['reference']??''));$note=trim((string)($b['note']??''));$label=$type==='BANK_CHARGE'?'Bank charge':($type==='INTEREST_CHARGED'?'Interest charged by bank':'Interest received from bank');$bankExtra=['bankAccountId'=>$bankId,'bankName'=>$bank['bankName'],'bankAccountTitle'=>$bank['accountTitle'],'currency'=>'PKR'];if($type==='INTEREST_RECEIVED')$lines=[bde_line('1110',$amount,0,$names,$bankExtra),bde_line('4400',0,$amount,$names,['bankDirectType'=>$type])];else $lines=[bde_line('6800',$amount,0,$names,['bankDirectType'=>$type]),bde_line('1110',0,$amount,$names,$bankExtra)];$dr=round(array_sum(array_column($lines,'debit')),2);$cr=round(array_sum(array_column($lines,'credit')),2);if(abs($dr-$cr)>.005)throw new RuntimeException('Direct bank entry did not balance.');$jid=bde_next((array)$s['journals']);$reference=$ref!==''?$ref:$jid;$s['journals'][$jid]=['id'=>$jid,'entity'=>$entity,'date'=>$date,'sourceType'=>'BANK_RECON_DIRECT_ENTRY','reference'=>$reference,'narration'=>$label.($note!==''?' — '.$note:''),'lines'=>$lines,'totalDebit'=>$dr,'totalCredit'=>$cr,'status'=>'Posted','meta'=>['bankAccountId'=>$bankId,'bankName'=>$bank['bankName'],'bankAccountTitle'=>$bank['accountTitle'],'bankDirectType'=>$type,'note'=>$note,'createdFrom'=>'Bank Reconciliation'],'createdAt'=>gmdate('c'),'createdBy'=>(string)($u['full_name']??$u['username']??'Accounts'),'userId'=>(int)($u['id']??0),'reversalOf'=>null];$s['revision']=(int)($s['revision']??0)+1;rewind($h);ftruncate($h,0);fwrite($h,json_encode($s,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));fflush($h);}finally{flock($h,LOCK_UN);fclose($h);}bde_out(['ok'=>true,'journalId'=>$jid,'reference'=>$reference,'type'=>$type,'amount'=>$amount,'revision'=>$s['revision']]);}catch(Throwable $e){bde_out(['ok'=>false,'error'=>'The bank statement entry could not be posted.'],500);}